CREATE SCHEMA dootah_cloud;
SET search_path TO dootah_cloud;
CREATE TABLE migrations(version integer PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE users(id uuid PRIMARY KEY, email text UNIQUE NOT NULL, password_hash text NOT NULL);
CREATE TABLE organizations(id uuid PRIMARY KEY, name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE members(organization_id uuid REFERENCES organizations, user_id uuid REFERENCES users, role text NOT NULL CHECK(role IN ('Owner','Developer','Viewer')), PRIMARY KEY(organization_id,user_id));
CREATE TABLE credentials(id uuid PRIMARY KEY, digest text UNIQUE NOT NULL, kind text NOT NULL CHECK(kind IN ('session','api','installation','enrollment')), user_id uuid REFERENCES users, organization_id uuid REFERENCES organizations, app_id uuid, environment_id uuid, installation_id uuid, scopes text[] NOT NULL DEFAULT '{}', expires_at timestamptz NOT NULL, revoked_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX credentials_owner ON credentials(organization_id,created_at,id);
CREATE TABLE apps(id uuid PRIMARY KEY, organization_id uuid NOT NULL REFERENCES organizations, name text NOT NULL, delivery_key text UNIQUE NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,id));
CREATE TABLE environments(id uuid PRIMARY KEY, organization_id uuid NOT NULL, app_id uuid NOT NULL, name text NOT NULL, runtime text NOT NULL, contract jsonb NOT NULL, head uuid, directive_branch text, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,id), UNIQUE(organization_id,app_id,id), UNIQUE(app_id,name), FOREIGN KEY(organization_id,app_id) REFERENCES apps(organization_id,id));
CREATE TABLE releases(id uuid PRIMARY KEY, organization_id uuid NOT NULL, app_id uuid NOT NULL, environment_id uuid NOT NULL, runtime text NOT NULL, runtime_abi integer NOT NULL CHECK(runtime_abi=2), logic_abi integer NOT NULL CHECK(logic_abi=1), revision text NOT NULL, hash text NOT NULL, artifact jsonb NOT NULL, creator uuid NOT NULL REFERENCES users, status text NOT NULL CHECK(status IN ('draft','ready','rolling_out','paused','active','rolled_back','killed','failed')), percentage integer NOT NULL CHECK(percentage BETWEEN 0 AND 100), version integer NOT NULL DEFAULT 1, upstream_id text, upstream_uuid uuid, branch text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,id), UNIQUE(organization_id,app_id,environment_id,id), FOREIGN KEY(organization_id,app_id,environment_id) REFERENCES environments(organization_id,app_id,id));
CREATE TABLE installations(id uuid NOT NULL, organization_id uuid NOT NULL, app_id uuid NOT NULL, environment_id uuid NOT NULL, runtime text NOT NULL, native_version text NOT NULL, sdk_version text NOT NULL, embedded_id uuid, active_release uuid, active_at timestamptz, last_seen timestamptz NOT NULL DEFAULT now(), created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(organization_id,id), UNIQUE(organization_id,app_id,environment_id,id), FOREIGN KEY(organization_id,app_id,environment_id) REFERENCES environments(organization_id,app_id,id), FOREIGN KEY(organization_id,active_release) REFERENCES releases(organization_id,id));
CREATE TABLE events(id uuid NOT NULL, organization_id uuid NOT NULL, app_id uuid NOT NULL, environment_id uuid NOT NULL, installation_id uuid NOT NULL, release_id uuid, type text NOT NULL, activation_id uuid NOT NULL, occurred_at timestamptz NOT NULL, received_at timestamptz NOT NULL DEFAULT now(), digest text NOT NULL, metadata jsonb NOT NULL, PRIMARY KEY(organization_id,installation_id,id), FOREIGN KEY(organization_id,app_id,environment_id,installation_id) REFERENCES installations(organization_id,app_id,environment_id,id), FOREIGN KEY(organization_id,app_id,environment_id,release_id) REFERENCES releases(organization_id,app_id,environment_id,id));
CREATE INDEX events_release ON events(organization_id,release_id,type,occurred_at);
CREATE INDEX installations_environment ON installations(organization_id,environment_id,last_seen);
CREATE TABLE operations(id uuid PRIMARY KEY, organization_id uuid NOT NULL REFERENCES organizations, resource_id uuid NOT NULL, actor uuid NOT NULL REFERENCES users, key text NOT NULL, digest text NOT NULL, action text NOT NULL, status text NOT NULL, receipt jsonb, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,key));
CREATE TABLE grants(organization_id uuid NOT NULL, installation_id uuid NOT NULL, release_id uuid NOT NULL, PRIMARY KEY(organization_id,installation_id,release_id), FOREIGN KEY(organization_id,release_id) REFERENCES releases(organization_id,id));
CREATE TABLE audit(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, organization_id uuid NOT NULL REFERENCES organizations, actor uuid NOT NULL, action text NOT NULL, resource_id uuid NOT NULL, metadata jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX audit_org ON audit(organization_id,id);
CREATE FUNCTION immutable_audit() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'audit is append only'; END $$;
CREATE TRIGGER audit_immutable BEFORE UPDATE OR DELETE ON audit FOR EACH ROW EXECUTE FUNCTION immutable_audit();
CREATE TABLE rate_limits(key text PRIMARY KEY, window_id bigint NOT NULL, count integer NOT NULL);
INSERT INTO migrations(version) VALUES(1);
